    for i in range(H):
        for j in range(W):
            if g[i][j] and not seen[i][j]:
                c=g[i][j]; q=deque([(i,j)]); seen[i][j]=True; cells=[]
                while q:
                    y,x=q.popleft(); cells.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and g[ny][nx]==c and not seen[ny][nx]:
                            seen[ny][nx]=True; q.append((ny,nx))
                out.append((c,cells))
